import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Campaign and task usability","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/campaign-task-ux/spec.md","filePath":"feature/media-package-campaign/campaign-task-ux/spec.md"}'),n={name:"feature/media-package-campaign/campaign-task-ux/spec.md"};function r(o,e,c,d,l,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<p>&gt; Checkpoint 2026-10-17: restored specification and historical verification for retained Media Package/Campaign UI. Task UI changes described as rolled back remain out of this UX scope. API/classification changes after this checkpoint are governed by the Media Package package-simplification spec; historical fixture test results are not a new verification run.</p><h1 id="campaign-and-task-usability" tabindex="-1">Campaign and task usability <a class="header-anchor" href="#campaign-and-task-usability" aria-label="Permalink to &quot;Campaign and task usability&quot;">​</a></h1><p>&gt; Scope update: the user requested rollback of all UI changes outside Media Package and Media Campaign. The Task criteria below are historical and no longer describe the active implementation. The four changed Task source files and two Task locale files were restored to their pre-session HEAD; the newly added WorkspaceTaskView.tsx was removed. Campaign improvements remain.</p><h2 id="objective-and-user-story" tabindex="-1">Objective and user story <a class="header-anchor" href="#objective-and-user-story" aria-label="Permalink to &quot;Objective and user story&quot;">​</a></h2><p>Managers and clients need to understand the next campaign step. Task users need to find and open work without misleading controls or excessive loading.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Preserve BrandHub&#39;s existing typography, theme tokens, orange CTA, spacing and shared UI components. Support light/dark themes; add no palette or dependencies.</li><li>Campaign prerequisites include a link to the workspace media package. Existing campaigns show contextual guidance and links to plan/review/delivery sections and tasks. Do not change approval, deployment or role rules.</li><li>Task search waits 300 ms after typing; Enter submits immediately. Reset clears search and filters even when there are no results. Request sequencing still prevents stale results.</li><li>Task titles and sorting are keyboard accessible. Remove selection controls with no bulk action and dropdown affordances on read-only status badges.</li><li>Task view is preserved in the URL, retaining the selected task parameter.</li><li>Empty tasks explain their source; campaign links appear only for roles allowed to access campaigns.</li><li>All new strings use <code>campaign.ux.*</code> and <code>tasks.ux.*</code>, added in parallel to <code>src/i18n/locales/{vi,en}/{campaign,tasks}.json</code>.</li></ul><h2 id="ui-states-and-errors" tabindex="-1">UI states and errors <a class="header-anchor" href="#ui-states-and-errors" aria-label="Permalink to &quot;UI states and errors&quot;">​</a></h2><p>Loading and failure must not show campaign guidance based on an assumed draft. Preserve retry, unsaved task guards, campaign discard confirmation, loading feedback and API errors. Empty and filtered-empty task states have distinct recovery actions.</p><h2 id="api-contract-and-scope" tabindex="-1">API contract and scope <a class="header-anchor" href="#api-contract-and-scope" aria-label="Permalink to &quot;API contract and scope&quot;">​</a></h2><p>Existing APIs and role checks remain authoritative. No backend/schema changes, automatic approval/deployment, mobile changes or redesign.</p><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>Type check, build, lint changed files, existing relevant checks and browser checks with controlled fixtures; record actual validation and limits in test.md.</p>',13)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
